		clock = RealClock
	}
	now := clock.Now()
	return &Limiter{
		rate:  rate,
		burst: float64(burst),
		tokens: float64(burst),
		last:  now,
		clock: clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill based on elapsed time since last event.
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = now
	}

	need := float64(n)
	if l.tokens < need {
		return false
	}
	l.tokens -= need
	return true
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// Tokens returns the current number of available tokens (advanced to now).
func (l *Limiter) Tokens() float64 {
	now := l.clock.Now()
	l.mu.Lock()
	defer l.mu.Unlock()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		t := l.tokens + elapsed*l.rate
		if t > l.burst {
			t = l.burst
		}
		return t
	}
	return l.tokens
}
