package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the system time.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be created with New; the zero value is not usable.
type Limiter struct {
	mu       sync.Mutex
	burst    float64   // bucket capacity
	tokens   float64   // current tokens
	rate     float64   // tokens per second
	last     time.Time // last refill time
	clock    Clock
}

var ErrInvalidConfig = errors.New("ratelimit: rate and burst must be > 0")

// New returns a Limiter that refills at rate tokens per second with a
// capacity of burst. The bucket starts full.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 || burst <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		burst:  float64(burst),
		tokens: float64(burst),
		rate:   rate,
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// refill advances the bucket to time t, adding accrued tokens.
// Caller must hold l.mu.
func (l *Limiter) refill(t time.Time) {
	elapsed := t.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = t
	}
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are consumed.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// Tokens returns the number of tokens currently available (approximate
// under concurrency; primarily for tests and observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}
