// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by time.Now.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds up to Burst tokens and refills at Rate tokens per second.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	burst    int
	rate     float64 // tokens per second
	clock    Clock
}

var ErrInvalidConfig = errors.New("ratelimit: burst must be > 0 and rate must be > 0")

// New creates a Limiter starting full with burst tokens.
func New(burst int, rate float64, clock Clock) (*Limiter, error) {
	if burst <= 0 || rate <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = RealClock()
	}
	return &Limiter{
		tokens: float64(burst),
		last:   clock.Now(),
		burst:  burst,
		rate:   rate,
		clock:  clock,
	}, nil
}

// advance refills tokens based on elapsed time since last refill.
// Caller must hold l.mu.
func (l *Limiter) advance(now time.Time) {
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.burst) {
			l.tokens = float64(l.burst)
		}
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are consumed; otherwise the bucket is unchanged.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// Tokens returns the current number of available tokens (for diagnostics).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(l.clock.Now())
	return l.tokens
}
